{%- if allergens and allergens.size > 0 -%}
<ul class="allergen-badges" aria-label="{{ label | default: 'Allergens' | escape }}">
{%- for allergen in allergens -%}
<li class="allergen-badge" title="Contains {{ allergen }}">{{ allergen | escape }}</li>
{%- endfor -%}
</ul>
{%- endif -%}

